// swift-tools-version: 6.3
import PackageDescription

// The Alula demo: one application exercising the whole ecosystem.
//
// Two package dependencies, not eight. `alula` carries the framework and the
// layers on top of it; `alula-data` carries persistence and caching, with the
// Postgres driver requested by trait. Everything below is a product of one of
// those two.
let package = Package(
    name: "App",
    platforms: [.macOS(.v15)],
    products: [
        .executable(name: "App", targets: ["App"])
    ],
    dependencies: [
        // "defaults" keeps the Web trait on; "Security" adds the resource
        // server. Naming any trait means "default" must be named too.
        .package(url: "https://github.com/Alula-Framework/alula.git", from: "0.38.0", traits: ["Security"]),
        .package(url: "https://github.com/Alula-Framework/alula-data.git", from: "0.13.0", traits: ["Postgres"]),
    ],
    targets: [
        .executableTarget(
            name: "App",
            dependencies: [
                .product(name: "AlulaCore", package: "alula"),
                .product(name: "AlulaWeb", package: "alula"),
                .product(name: "AlulaTransport", package: "alula"),
                .product(name: "AlulaActuator", package: "alula"),
                .product(name: "AlulaScheduler", package: "alula"),
                .product(name: "AlulaSecurityCore", package: "alula"),
                .product(name: "AlulaPubSub", package: "alula"),
                .product(name: "AlulaRateLimit", package: "alula"),
                .product(name: "AlulaChannels", package: "alula"),
                .product(name: "AlulaChannelsProtocol", package: "alula"),
                .product(name: "AlulaPresence", package: "alula"),
                .product(name: "AlulaDataPostgres", package: "alula-data"),
                .product(name: "AlulaMigrate", package: "alula-data"),
                .product(name: "AlulaSchedulerPostgres", package: "alula-data"),
                .product(name: "AlulaCache", package: "alula-data"),
            ],
            plugins: [
                .plugin(name: "AlulaRegistrationPlugin", package: "alula")
            ]
        ),

        // Migration files live in their own target so AlulaMigratePlugin can
        // scan them and generate the _allMigrations() registry at build time.
        // The app target does NOT depend on this — migrations never run at boot.
        .target(
            name: "Migrations",
            dependencies: [.product(name: "AlulaMigrate", package: "alula-data")],
            plugins: [.plugin(name: "AlulaMigratePlugin", package: "alula-data")]
        ),

        .executableTarget(
            name: "migrate",
            dependencies: [
                "Migrations",
                .product(name: "AlulaMigrateCLI", package: "alula-data"),
            ]
        ),

        .testTarget(
            name: "AppTests",
            dependencies: [
                "App",
                .product(name: "AlulaCore", package: "alula"),
                .product(name: "AlulaWeb", package: "alula"),
                .product(name: "AlulaWebTesting", package: "alula"),
                .product(name: "AlulaSessionsTesting", package: "alula"),
                .product(name: "AlulaRateLimitTesting", package: "alula"),
                .product(name: "AlulaChannels", package: "alula"),
                .product(name: "AlulaChannelsTesting", package: "alula"),
                .product(name: "AlulaChannelsClient", package: "alula"),
                .product(name: "AlulaPresence", package: "alula"),
                .product(name: "AlulaPresenceClient", package: "alula"),
                .product(name: "AlulaPubSubTesting", package: "alula"),
                .product(name: "AlulaDataPostgres", package: "alula-data"),
                .product(name: "AlulaCache", package: "alula-data"),
            ]
        ),
    ]
)

"""#,
            "Sources/App/Channels/RoomChannel.swift": #"""
import AlulaChannels
import AlulaChannelsProtocol
import AlulaCore
import AlulaPresence
import AlulaWeb
import Foundation

/// The live half of the chat room: `ChatController` is its history, this is
/// its present tense.
///
/// One registration serves every room — the pattern is `room:*`, and Channels
/// creates one instance per (socket, topic), so `topic` identifies which room
/// this instance is holding.
///
/// Three layers meet here and each keeps its own job:
///
/// - **Channels** owns the per-connection protocol: join, events, replies.
/// - **PubSub** does the fan-out, so a broadcast reaches subscribers on every
///   node without this code knowing whether there is one node or twenty.
/// - **Presence** answers "who is in this room", CRDT-merged across the
///   cluster. Nothing here ever *removes* a presence: tracking is bound to
///   the socket's membership, so every teardown path — client leave, dropped
///   transport, heartbeat timeout, shutdown — untracks structurally.
struct RoomChannel: Channel {
    let broadcaster: ChannelBroadcaster
    let presence: any Presence
    let chat: any RoomStore
    let digests: any DigestInvalidating

    /// The join is the authorization gate, and the identity it gates on was
    /// established during the HTTP upgrade — before the WebSocket existed.
    /// By the time a frame can arrive, the question is already settled.
    func join(_ topic: String, socket: Socket) async -> JoinResult {
        guard let principal = socket.principal else { return .reject(.unauthenticated) }
        guard let slug = Self.roomSlug(from: topic) else {
            return .reject(JoinRejection("malformed_topic"))
        }

        // The room must exist. Letting anyone join "room:anything" would make
        // presence lists for rooms that were never opened.
        let room: Room?
        do {
            room = try await chat.room(slug: slug, messageLimit: 0)
        } catch {
            return .reject(JoinRejection("lookup_failed"))
        }
        guard let room, !room.archived else {
            return .reject(JoinRejection(room == nil ? "no_such_room" : "room_archived"))
        }

        await presence.track(
            topic: topic,
            key: principal.subject,
            payload: ["status": "online", "since": Self.timestamp()],
            socket: socket)
        // State first, then diffs. `sendState` waits for the membership to be
        // fully established, so the client sees reply → state → diffs with no
        // window a change could fall through.
        await presence.sendState(topic: topic, to: socket)

        return .ok(initialState: ["room": .string(room.slug), "name": .string(room.name)])
    }

    func handle(_ event: InboundEvent, socket: Socket) async -> HandleResult {
        guard let principal = socket.principal else { return .error(reason: "unauthenticated") }

        switch event.event {
        case "new_msg":
            return await postMessage(event, from: principal.subject, socket: socket)

        case "status":
            guard let status = event.payload["status"]?.stringValue,
                Self.allowedStatuses.contains(status)
            else {
                return .error(reason: "status must be one of: \(Self.allowedStatuses.sorted().joined(separator: ", "))")
            }
            await presence.update(
                topic: event.topic,
                key: principal.subject,
                payload: ["status": status, "since": Self.timestamp()],
                socket: socket)
            return .reply(["status": .string(status)])

        default:
            // Naming the event back is safe — it came from this client — and
            // saves a round trip through the server log to find a typo.
            return .error(reason: "unknown_event: \(event.event)")
        }
    }

    // MARK: - Posting

    /// Persist first, broadcast second.
    ///
    /// The order matters and is the interesting part of this file: a message
    /// that fans out to twenty subscribers and then fails to insert has been
    /// *seen* by everyone and *exists* for no one, and no amount of retrying
    /// puts that back. Writing first means the worst case is a message that
    /// is durable but arrives late — which the client's own history fetch
    /// repairs on its next load.
    private func postMessage(
        _ event: InboundEvent, from sender: String, socket: Socket
    ) async -> HandleResult {
        guard let body = event.payload["body"]?.stringValue, !body.isEmpty else {
            return .error(reason: "body is required")
        }
        guard let slug = Self.roomSlug(from: event.topic) else {
            return .error(reason: "malformed_topic")
        }

        do {
            guard let room = try await chat.room(slug: slug, messageLimit: 0) else {
                return .error(reason: "no_such_room")
            }
            let authors = try await chat.authorIDs(forNames: [sender])
            let message = ChatMessage(
                id: UUID(), room: room.slug, roomID: room.id, sender: sender,
                body: body, authorID: authors[sender], parentID: nil,
                mentions: Self.mentions(in: event.payload), sentAt: Date())
            let stored = try await chat.post([message])

            // Fan-out is PubSub's job, not this channel's — this call reaches
            // subscribers on every node without knowing how many there are.
            //
            // `excluding:` keeps the sender from seeing their own message
            // twice: they receive the canonical row as the reply below, so
            // the broadcast is for everyone else.
            let persisted = stored.first ?? message
            await broadcaster.broadcast(
                topic: event.topic,
                event: "new_msg",
                payload: Self.wire(persisted),
                excluding: socket)

            // Same table, same derived digests, same eviction as the REST
            // path — the two write paths cannot be allowed to disagree about
            // when a cached aggregate went stale.
            try? await digests.messagesChanged()

            return .reply(Self.wire(persisted))
        } catch {
            // The reason is deliberately coarse. Detail belongs in the log,
            // not on a wire a client reads.
            return .error(reason: "post_failed")
        }
    }

    // MARK: - Helpers

    static let allowedStatuses: Set<String> = ["online", "away", "typing"]

    /// `"room:general"` → `"general"`. Returns nil for anything that is not
    /// this channel's shape, so a malformed topic is refused rather than
    /// silently treated as a room named "".
    static func roomSlug(from topic: String) -> String? {
        guard topic.hasPrefix("room:") else { return nil }
        let slug = String(topic.dropFirst("room:".count))
        return slug.isEmpty ? nil : slug
    }

    static func mentions(in payload: JSONValue) -> [String] {
        guard case .array(let raw)? = payload["mentions"] else { return [] }
        return raw.compactMap(\.stringValue)
    }

    static func timestamp() -> String { Date().formatted(.iso8601) }

    /// One place deciding what a message looks like on the wire, so the
    /// WebSocket broadcast and any future REST push cannot drift apart.
    static func wire(_ message: ChatMessage) -> JSONValue {
        [
            "id": .string(message.id.uuidString),
            "room": .string(message.room),
            "sender": .string(message.sender),
            "body": .string(message.body),
            "mentions": .array(message.mentions.map(JSONValue.string)),
            "sentAt": .string(message.sentAt.formatted(.iso8601)),
        ]
    }
}

"""#,
            "Sources/App/Controllers/AttachmentController.swift": #"""
import AlulaCore
import AlulaWeb
import Foundation

/// File upload, both halves of alula 0.7.0 at once: the handler takes
/// `body: RequestBodyStream`, so the transport hands bytes through as they
/// arrive instead of buffering the request — that (plus `maxBodyBytes:`
/// overriding the global cap for just this route) is what lets an upload
/// accept far more than any sane global body limit. The stream feeds
/// `request.multipart()`, which parses parts without ever holding a file
/// in memory.
///
/// The demo digests instead of storing: what to *do* with uploaded bytes
/// (disk layout, object storage, virus scanning) is an application
/// decision this template shouldn't make for you, while the wire handling
/// is exactly what you'd keep. Swap the hasher loop for writes to your
/// storage of choice and the rest stands.
@Controller
struct AttachmentController {

    struct Received: Codable, ResponseEncodable {
        let field: String
        let filename: String?
        let contentType: String?
        let bytes: Int
    }

    @PostRoute("/attachments", maxBodyBytes: 64 << 20)
    func upload(_ context: RequestContext, body: RequestBodyStream) async throws -> [Received] {
        var received: [Received] = []
        for try await part in try context.request.multipart() {
            if part.filename != nil {
                // A file part: consume the stream chunk by chunk. Constant
                // memory no matter the size — this loop is where your
                // storage write goes.
                var bytes = 0
                for try await chunk in part.body {
                    bytes += chunk.count
                }
                received.append(
                    Received(
                        field: part.name,
                        filename: part.filename,
                        contentType: part.contentType?.essence,
                        bytes: bytes))
            } else {
                // An ordinary form field riding along with the file.
                let value = try await part.text()
                received.append(
                    Received(
                        field: part.name, filename: nil, contentType: nil,
                        bytes: value.utf8.count))
            }
        }
        guard !received.isEmpty else {
            throw HTTPError(.badRequest, "multipart body had no parts")
        }
        return received
    }
}

"""#,
            "Sources/App/Controllers/ChatController.swift": #"""
import Foundation
import AlulaChannels
import AlulaChannelsProtocol
import AlulaCore
import AlulaWeb
import AlulaDataCore
import AlulaDataPostgres
import AlulaPresence
import AlulaSecurityCore
import PostgresNIO
import Synchronization

// MARK: - Request bodies

struct OpenRoomRequest: Codable {
    let slug: String
    let name: String
    let greeting: String
}

struct PostMessagesRequest: Codable {
    struct Line: Codable {
        let sender: String
        let body: String
        let mentions: [String]?
        /// Set to make this line a reply — the self-reference the thread
        /// endpoint reads back.
        let replyTo: UUID?
    }
    let roomSlug: String
    let lines: [Line]
}

struct ArchiveRoomRequest: Codable {
    let destinationSlug: String
}

struct RedactRequest: Codable {
    let sender: String
    let roomSlug: String
}

/// One person in a room, as `GET /rooms/:slug/who` reports them.
struct Occupant: Codable, Sendable, ResponseEncodable {
    let key: String
    /// How many live connections this identity holds in the room.
    let connections: Int
    let status: String
}

// MARK: - Controller

/// The HTTP surface over `ChatRepository` — one endpoint per query shape, so
/// each Hangar feature is something you can actually curl.
///
/// Handlers here stay thin on purpose: resolve, delegate, translate errors.
/// Everything interesting about the queries is in `ChatRepository`.
@Controller
struct ChatController {

    /// Injected, not resolved. A controller is constructed per request from
    /// the component graph, so what it needs is a property the build wires.
    /// These were `context.resolve` calls in every method — a lookup per
    /// request for values the composition root has held since start-up.
    @Inject var chat: ChatRepository
    @Inject var digests: RoomDigestService

    /// Provided by `AlulaPresenceModule` and `AlulaChannelsModule` rather
    /// than scanned from this target, so they are roots of the graph. The
    /// marker says the scanner is right not to have found them.
    // alula:hand-registered
    @Inject var presence: any Presence
    // alula:hand-registered
    @Inject var broadcaster: ChannelBroadcaster

    // MARK: Associations

    /// `GET /rooms/:slug` — a room with a page of messages, each message's
    /// author, and each message's topics, as one JSON document.
    ///
    /// Unloaded associations serialize as `null`; loaded ones as their value.
    @GetRoute("/rooms/:slug")
    func room(_ context: RequestContext, slug: String) async throws -> Room {
        guard let room = try await chat.room(slug: slug) else {
            throw HTTPError(.notFound, "no room '\(slug)'")
        }
        return room
    }

    /// `GET /users/:id/history` — a user with everything they wrote.
    /// The association crosses a nullable foreign key.
    @GetRoute("/users/:id/history")
    func history(_ context: RequestContext, id: UUID) async throws -> User {
        guard let user = try await chat.user(id: id) else {
            throw HTTPError(.notFound, "no user \(id)")
        }
        return user
    }

    // MARK: Joins

    /// `GET /messages/recent` — a three-table join, flattened.
    @GetRoute("/messages/recent")
    func recent(_ context: RequestContext) async throws -> [MessageCard] {
        let limit = context.request.queryParam("limit").flatMap(Int.init) ?? 25
        return try await chat.recentCards(limit: limit)
    }

    /// `GET /messages/:id/thread` — `messages` joined to itself under two
    /// aliases, so each reply arrives next to the message it answers.
    @GetRoute("/messages/:id/thread")
    func thread(_ context: RequestContext, id: UUID) async throws -> [ThreadEntry] {
        try await chat.thread(rootID: id)
    }

    // MARK: Aggregates

    /// `GET /activity?min=3` — GROUP BY with HAVING.
    /// Served from the cache when warm — see `RoomDigestService`. Posting a
    /// message evicts it, so the "post then reload" loop stays truthful.
    @GetRoute("/activity")
    func activity(_ context: RequestContext) async throws -> [RoomActivity] {
        let minimum = context.request.queryParam("min").flatMap(Int.init) ?? 1
        return try await digests.activity(minimumMessages: minimum)
    }

    /// `GET /headlines` — `DISTINCT ON`, one row per room.
    @GetRoute("/headlines")
    func headlines(_ context: RequestContext) async throws -> [RoomHeadline] {
        try await digests.headlines()
    }

    // MARK: Runtime-sourced filters

    /// `GET /messages/search?sender=ada&redacted=false` — every query
    /// parameter is checked against the allowlist on `ChatMessage` before it
    /// can affect the SQL. An unlisted field is a 400, not a silent no-op.
    @GetRoute("/messages/search")
    func search(_ context: RequestContext) async throws -> [ChatMessage] {
        var filters: [String: DynamicFilterValue] = [:]
        for item in context.request.queryItems where item.name != "limit" {
            // Query strings are untyped; the allowlist's column types are not.
            // Handing "true" to a Bool column is a mismatch the filter layer
            // rejects, so parse the obvious shapes here.
            switch item.value {
            case "true": filters[item.name] = .bool(true)
            case "false": filters[item.name] = .bool(false)
            default: filters[item.name] = .string(item.value)
            }
        }
        let limit = context.request.queryParam("limit").flatMap(Int.init) ?? 50
        do {
            return try await chat.search(filters, limit: limit)
        } catch let error as HangarError {
            throw HTTPError(.badRequest, "\(error)")
        }
    }

    // MARK: Presence

    /// `GET /rooms/:slug/who` — the room's live occupancy, over plain HTTP.
    ///
    /// Presence is a cluster-wide CRDT, not a per-socket list, so this answers
    /// for the whole cluster even though this node only holds some of those
    /// connections. It exists mostly so presence is observable with `curl`:
    /// the real consumers are WebSocket clients, which get a
    /// `alula:presence_state` on join and `alula:presence_diff`s after.
    @GetRoute("/rooms/:slug/who")
    func who(_ context: RequestContext, slug: String) async throws -> Response {
        let entries = await presence.list(topic: "room:\(slug)")
        return try .json(
            entries.map { entry in
                // One identity can be present many times — three browser tabs
                // are one key with three metas. Collapsing that to a bare list
                // of names would lose the distinction the data structure
                // exists to keep, so the count travels with the name.
                Occupant(
                    key: entry.key,
                    connections: entry.metas.count,
                    status: entry.metas.compactMap { $0.payload["status"] }.first ?? "online")
            })
    }

    // MARK: Writes

    /// `POST /rooms` — room and opening message as one named `Multi`.
    ///
    /// The unit of work is a `Multi`: steps decided before they run, named,
    /// and executed in one transaction that Hangar opens. There is no
    /// ambient coordinator to bind and nothing outside this call that could
    /// be nesting a transaction around it — the boundary is the closure you
    /// can see. `POST /chatUser` on `UserController` is the other shape,
    /// where the transaction lives inside the repository method.
    @PostRoute("/rooms")
    func openRoom(_ context: RequestContext, body: OpenRoomRequest) async throws -> Response {
        do {
            let room = try await chat.openRoom(
                slug: body.slug, name: body.name, greeting: body.greeting)
            return try .json(room, status: .created)
        } catch let error as ChatError {
            throw error.asHTTPError
        }
    }

    /// `POST /messages` — a batch of messages as one multi-row INSERT.
    @PostRoute("/messages")
    func post(_ context: RequestContext, body: PostMessagesRequest) async throws -> Response {
        guard let room = try await chat.room(slug: body.roomSlug, messageLimit: 0) else {
            throw HTTPError(.notFound, "no room '\(body.roomSlug)'")
        }
        // One query for every distinct sender, not one per line.
        let authors = try await chat.authorIDs(forNames: body.lines.map(\.sender))
        let now = Date()
        let messages = body.lines.map { line in
            ChatMessage(
                id: UUID(), room: room.slug, roomID: room.id, sender: line.sender,
                body: line.body, authorID: authors[line.sender], parentID: line.replyTo,
                mentions: line.mentions ?? [], sentAt: now)
        }
        let stored = try await chat.post(messages)

        // The REST and WebSocket paths write to the same table, so they must
        // fan out to the same subscribers. Anything holding a
        // `ChannelBroadcaster` can broadcast — a handler, a background job,
        // another node — and PubSub delivers it. Without this, a message
        // posted over HTTP would be invisible to everyone currently watching
        // the room over a socket until they reloaded.
        for message in stored {
            await broadcaster.broadcast(
                topic: "room:\(message.room)",
                event: "new_msg",
                payload: RoomChannel.wire(message))
        }
        // The digests are derived from this table; a write makes them stale.
        await digests.messagesChanged()

        return try .json(stored, status: .created)
    }

    /// `POST /topics/:label` — find-or-create without a read-then-write race.
    @PostRoute("/topics/:label")
    func topic(_ context: RequestContext, label: String) async throws -> Topic {
        return try await chat.topic(label: label)
    }

    /// `POST /messages/:id/topics/:label` — tag a message, creating the
    /// topic on first use. Preloading `\.topics` afterwards reads it back
    /// through the join table.
    @PostRoute("/messages/:id/topics/:label")
    func tag(_ context: RequestContext, id: UUID, label: String) async throws -> Topic {
        try await chat.tag(messageID: id, label: label)
    }

    /// `POST /rooms/:slug/archive` — row lock inside a serializable
    /// transaction, retried on a serialization failure.
    @PostRoute("/rooms/:slug/archive")
    func archive(_ context: RequestContext, slug: String, body: ArchiveRoomRequest) async throws -> Response {
        guard let source = try await chat.room(slug: slug, messageLimit: 0),
            let destination = try await chat.room(slug: body.destinationSlug, messageLimit: 0)
        else {
            throw HTTPError(.notFound, "both rooms must exist")
        }
        do {
            let moved = try await chat.archive(
                roomID: source.id, movingMessagesTo: destination.id)
            return try .json(["moved": moved])
        } catch let error as ChatError {
            throw error.asHTTPError
        }
    }

    /// `POST /messages/redact` — one UPDATE over every matching row.
    ///
    /// Redaction is moderation, so it needs a role rather than merely a
    /// logged-in user. `requireRole` is the handler-level guard: 401 with no
    /// principal, 403 with the wrong one. The alternative — registering
    /// `requireAuthentication` as middleware — protects *every* route, which
    /// is the wrong shape for an app whose reads are public.
    ///
    ///     curl -XPOST localhost:8080/messages/redact \
    ///          -H 'Authorization: Bearer demo:ada:moderator' ...
    @PostRoute("/messages/redact")
    func redact(_ context: RequestContext, body: RedactRequest) async throws -> Response {
        try context.requireRole("moderator")
        guard let room = try await chat.room(slug: body.roomSlug, messageLimit: 0) else {
            throw HTTPError(.notFound, "no room '\(body.roomSlug)'")
        }
        let redacted = try await chat.redactAll(sender: body.sender, inRoom: room.id)
        return try .json(["redacted": redacted])
    }

    /// `DELETE /messages?before=<ISO8601>` — one DELETE over every matching
    /// row, returning how many went.
    @DeleteRoute("/messages")
    func purge(_ context: RequestContext) async throws -> Response {
        try context.requireRole("moderator")
        guard let raw = context.request.queryParam("before"),
            let cutoff = try? Date(raw, strategy: .iso8601)
        else {
            throw HTTPError(.badRequest, "before must be an ISO 8601 timestamp")
        }
        let purged = try await chat.purge(before: cutoff)
        await digests.messagesChanged()
        return try .json(["purged": purged])
    }

    // MARK: Streaming

    /// `GET /rooms/:slug/export` — the room's history as line-delimited text.
    ///
    /// Rows decode one at a time off the connection rather than landing in an
    /// array first, so the *decode* cost is flat no matter how long the room's
    /// history is. The response body is still assembled in memory here:
    /// handing the row stream straight to `Response.streaming` would need a
    /// connection that outlives the request scope, which is a different piece
    /// of plumbing than the one this endpoint is demonstrating.
    @GetRoute("/rooms/:slug/export")
    func export(_ context: RequestContext, slug: String) async throws -> Response {
        guard let room = try await chat.room(slug: slug, messageLimit: 0) else {
            throw HTTPError(.notFound, "no room '\(slug)'")
        }
        let lines = Mutex<[String]>([])
        let count = try await chat.export(roomID: room.id) { line in
            lines.withLock {
                $0.append("\(line.sentAt.formatted(.iso8601))\t\(line.sender)\t\(line.body)")
            }
        }
        context.logger.info("exported \(count) messages from \(slug)")
        return .text(lines.withLock { $0.joined(separator: "\n") })
    }
}

extension ChatError {
    /// Repository failures translated at the edge, which is the only layer
    /// that should know about status codes.
    ///
    /// A duplicate slug arrives as Postgres SQLSTATE 23505 from inside the
    /// `Multi`'s failed step. That is a conflict the caller can fix, not a
    /// server fault, so it is a 409 — and reading the SQLSTATE is how you
    /// tell the two apart without parsing an error message.
    var asHTTPError: HTTPError {
        switch self {
        case .noSuchRoom(let id):
            return HTTPError(.notFound, "no room \(id)")
        case .upsertReturnedNothing(let label):
            return HTTPError(.internalServerError, "upsert returned no row for '\(label)'")
        case .multiStepFailed(let step, let underlying):
            if let psql = underlying as? PSQLError,
                psql.serverInfo?[.sqlState] == "23505"
            {
                return HTTPError(.conflict, "step '\(step)': that value already exists")
            }
            return HTTPError(.internalServerError, "step '\(step)' failed")
        }
    }
}

