            "Sources/App/Repos/RoomStoreProtocol.swift": #"""
import Foundation

/// The narrow slice of `ChatRepository` that `RoomChannel` actually needs.
///
/// Same reasoning as `UserRepositoryProtocol`, applied to the real-time path:
/// a struct wrapping a live database scope cannot be swapped out, a protocol
/// can. Depending on this instead of the concrete repository is what lets the
/// channel's join gate, its persist-before-broadcast ordering, and its
/// presence tracking be tested without a database anywhere in the loop.
///
/// It is deliberately three methods rather than all of `ChatRepository`. The
/// channel does not read history, run aggregates, or archive rooms, and a
/// seam that exposes more than its consumer uses is a seam that is expensive
/// to fake and easy to widen by accident.
///
/// `ChatRepository` conforms for free below — its signatures already match.
protocol RoomStore: Sendable {
    func room(slug: String, messageLimit: Int) async throws -> Room?
    func authorIDs(forNames names: [String]) async throws -> [String: UUID]
    func post(_ messages: [ChatMessage]) async throws -> [ChatMessage]
}

// The conformance itself lives in ChatRepository.swift: a protocol refining
// Sendable can only be conformed to in the type's own file.

"""#,
            "Sources/App/Repos/UserRepository.swift": #"""
import Foundation
import AlulaDataPostgres

/// The one thing signup can fail on that isn't a validation error.
enum SignupError: Error, Sendable {
    case noLobby
}

@Repository
struct UserRepository: UserRepositoryProtocol {
    /// The pool. Each method leases a connection for its own work and gives
    /// it back; a unit of work that must share one connection says so by
    /// putting every statement inside a single `withRepo`.
    // alula:hand-registered — PostgresDataModule registers the pool.
    @Inject var pool: PostgresDataSource

    func all() async throws -> [User] {
        try await pool.withRepo { repo in
            try await repo.all(User.all.order { $0.createdAt.desc() })
        }
    }

    func find(byID id: UUID) async throws -> User? {
        try await pool.withRepo { repo in
            try await repo.one(User.where { $0.id == id })
        }
    }

    func find(byEmail email: String) async throws -> User? {
        try await pool.withRepo { repo in
            try await repo.one(User.where { $0.email == email })
        }
    }

    /// Atomic signup. The lobby announcement is written FIRST so a
    /// duplicate-email failure on the user insert provably rolls it back.
    ///
    /// The transaction is Hangar's, and its extent is visible: one lease,
    /// one `transaction { }`, both writes on the `tx` repo it hands you.
    /// Using the outer `repo` inside would run that statement beside the
    /// transaction rather than in it — which is why the closure gives you a
    /// different one to use.
    func signup(name: String, email: String) async throws -> User {
        try await pool.withRepo { repo in
            try await repo.transaction { tx in
                // The lobby is a real row, not a free-text label, so the
                // announcement needs its id. Rooms are created by the
                // migration's backfill and by ChatRepository.openRoom.
                guard let lobby = try await tx.one(Room.where { $0.slug == "lobby" }) else {
                    throw SignupError.noLobby
                }
                try await tx.insert(
                    ChatMessage(
                        id: UUID(), room: lobby.slug, roomID: lobby.id, sender: "system",
                        body: "\(name) joined the demo", sentAt: Date()))
                let now = Date()
                return try await tx.insert(
                    User(id: UUID(), name: name, email: email, createdAt: now, updatedAt: now))
            }
        }
    }

    /// Dirty-column-only UPDATE (or INSERT) from a changeset — identity
    /// decides which, exactly as the changeset design's driver boundary
    /// specifies.
    func apply(_ changeset: Changeset<User>) async throws {
        try await pool.withRepo { repo in
            if changeset.original == nil {
                _ = try await repo.insert(changeset)
            } else {
                _ = try await repo.update(changeset)
            }
        }
    }
}

"""#,
            "Sources/App/Repos/UserRepositoryProtocol.swift": #"""
import AlulaDataPostgres
import Foundation

/// The seam `UserService` depends on instead of the concrete, Postgres-bound
/// `UserRepository` — a struct wrapping a live scope can't be swapped out
/// for anything; a protocol can. `UserService`'s `@Inject var
/// repository: (any UserRepositoryProtocol)` still resolves through the
/// ordinary `@Service` pipeline — the registration generator bridges this
/// existential key to a real `UserRepository` (tests bridge it to a fake
/// instead). `UserRepository` conforms below, for free — its method
/// signatures already match.
///
/// `apply` takes the `Changeset` itself (not `ValidatedChanges`): Hangar's
/// `Repo` consumes changesets directly (hangar-design §11.2) — validation
/// still throws before anything reaches the wire.
protocol UserRepositoryProtocol: Sendable {
    func all() async throws -> [User]
    func find(byID id: UUID) async throws -> User?
    func find(byEmail email: String) async throws -> User?
    func apply(_ changeset: Changeset<User>) async throws
}

"""#,
            "Sources/App/Security/DemoAccounts.swift": #"""
import AlulaCore
import AlulaSecurityCore

/// The accounts the demo's password sign-in checks against.
///
/// In memory, seeded at startup, so the demo runs with nothing to set up. A
/// real application implements `CredentialStore` over its own users table —
/// two methods, find by identifier and save a stronger hash — and provides
/// that here instead; see Docs/sign-in.md in alula. Subjects are opaque ids,
/// never the email address: when this application moves to an identity
/// provider, the subject is what every row keyed by user survives on.
///
/// Its own module for the same reason `DemoAuthModule` is: `SessionController`
