            "Tests/AppTests/RateLimitingTests.swift": #"""
import AlulaCore
import AlulaRateLimit
import AlulaRateLimitTesting
import AlulaSecurityCore
import AlulaWeb
import AlulaWebTesting
import HTTPTypes
import Testing

@testable import App

/// The demo limits by signed-in subject, falling back to the path. This
/// suite pins the part that is easy to get wrong: that two callers really do
/// have separate budgets, and that the limit is enforced rather than merely
/// configured.
@Suite("Rate limiting")
struct RateLimitingTests {
    private let store = RecordingRateLimitStore()

    /// The demo's own key rule, with a quota small enough to reach in a test.
    private func client(quota: RateLimitQuota = .perMinute(2)) throws -> TestClient {
        let validator: any TokenValidator = DemoTokenValidator()
        let security = AlulaSecurityModule(validator: validator)
        let limiting = RateLimiting(store: store, quota: quota) { context in
            context.principal?.subject ?? context.clientAddress?.host ?? "unknown"
        }
        // A route of this suite's own rather than a controller: what is
        // under test is the lane, and borrowing a controller would couple
        // this to whatever that controller happens to inject.
        let route = RouteRegistration(method: .get, path: "/health", source: "test") { _ in
            .text("ok")
        }
        return try TestClient(
            routes: [route],
            middleware: security.middleware
                + MiddlewareRegistration.lane(.default, [limiting]))
    }

    private func authorization(_ subject: String) -> HTTPFields {
        [.authorization: "Bearer demo:\(subject)"]
    }

    @Test("a caller over the quota is refused with a Retry-After")
    func refusesOverTheQuota() async throws {
        let client = try client()
        for _ in 0..<2 {
            #expect(await client.get("/health", headers: authorization("ada")).status == .ok)
        }
        let denied = await client.get("/health", headers: authorization("ada"))
        #expect(denied.status == .tooManyRequests)
        #expect(denied.header("retry-after") != nil)
        #expect(denied.header("x-ratelimit-remaining") == "0")
    }

    @Test("one noisy caller does not spend another's budget")
    func budgetsAreSeparate() async throws {
        let client = try client()
        for _ in 0..<3 { _ = await client.get("/health", headers: authorization("ada")) }
        #expect(
            await client.get("/health", headers: authorization("grace")).status == .ok,
            "grace has her own budget, because the key is the subject")
        #expect(store.callCount(for: "ada") == 3)
        #expect(store.callCount(for: "grace") == 1)
    }

    @Test("anonymous callers are keyed by their real address, not lumped into one bucket")
    func anonymousKeyedByAddress() async throws {
        let client = try client()
        _ = await client.execute(
            Request(method: .get, path: "/health", remoteAddress: PeerAddress(host: "203.0.113.9")))
        #expect(store.consumed.last?.key == "203.0.113.9")

        for _ in 0..<2 {
            _ = await client.execute(
                Request(method: .get, path: "/health", remoteAddress: PeerAddress(host: "203.0.113.20")))
        }
        #expect(
            await client.execute(
                Request(method: .get, path: "/health", remoteAddress: PeerAddress(host: "203.0.113.20"))
            ).status == .tooManyRequests,
            "the second anonymous caller reached its own limit — the first one's budget was untouched")
        #expect(
            await client.execute(
                Request(method: .get, path: "/health", remoteAddress: PeerAddress(host: "203.0.113.9"))
            ).status == .ok,
            "and still has its own budget left"
        )
    }

    @Test("an anonymous caller with no real socket behind it falls back to the unknown bucket")
    func noRemoteAddressFallsBack() async throws {
        // `TestClient.get` builds a `Request` with no `remoteAddress`, the
        // same shape a hand-built request in a snippet has. The key closure
        // still has to answer something.
        let client = try client()
        _ = await client.get("/health")
        #expect(store.consumed.last?.key == "unknown")
    }

    @Test("the quota replenishes")
    func replenishes() async throws {
        let client = try client()
        for _ in 0..<2 { _ = await client.get("/health", headers: authorization("ada")) }
        #expect(await client.get("/health", headers: authorization("ada")).status == .tooManyRequests)
        store.advance(by: .seconds(60))
        #expect(await client.get("/health", headers: authorization("ada")).status == .ok)
    }
}

"""#,
            "Tests/AppTests/RealtimeTests.swift": #"""
import AlulaChannels
import AlulaChannelsClient
import AlulaChannelsProtocol
import AlulaChannelsTesting
import AlulaCore
import AlulaPresence
import AlulaPresenceClient
import AlulaPubSub
import AlulaSecurityCore
import AlulaWeb
import AlulaWebTesting
import Foundation
import Testing

@testable import App

/// The demo's real-time path, end to end: a real `ChannelClient` over a real
/// upgrade, through the real Channels router, the real PubSub fan-out, and the
/// real Presence CRDT. Only the database is faked.
///
/// This is the suite that proves the thing the demo previously only claimed —
/// that a chat app built on Alula actually delivers messages and presence to
/// the people in the room.
/// Holds the demo's room channel, built from a fake store and the shared
/// presence — the same shape `AppModule`/`DemoChannelsModule` use, a value
/// the channels module is built *from*.
private struct RealtimeModule {
    let store: FakeRoomStore
    let channels: [ChannelRegistration]

    init(store: FakeRoomStore, presence: any Presence) {
        self.store = store
        self.channels = [
            // The broadcaster arrives per join; everything else is closed over.
            ChannelRegistration("room:*", source: "RealtimeModule") { channel in
                RoomChannel(
                    broadcaster: channel.broadcaster,
                    presence: presence,
                    chat: store,
                    digests: NoopDigests())
            }
        ]
    }
}

private struct Harness {
    let testClient: TestClient
    let store: FakeRoomStore
    /// The presence engine the room channel tracks into and the tests read.
    let presence: any Presence

    init(store: FakeRoomStore) throws {
        self.store = store
        let configuration = Configuration(values: [
            "alula.channels.heartbeat-check-interval-seconds": "0.05"
        ])
        // The wiring, written out: PubSub's bus and this module's declared
        // channels are what Channels is built from.
        let pubsub = try AlulaPubSubModule(configuration: configuration)
        // No adapter: a single-node test, stated rather than discovered.
        let presenceModule = try AlulaPresenceModule(
            configuration: configuration, localBus: pubsub.local, gossipBus: pubsub.bus)
        let presence = presenceModule.presence
        let realtime = RealtimeModule(store: store, presence: presence)
        let channels = try AlulaChannelsModule(
            bus: pubsub.bus, configuration: configuration, channels: realtime.channels)
        // The real route the application ships (`SocketController`), built the
        // way `alulaRoutes` builds it: the validator by value, the channels
        // stack from the channels module. This is what exercises the upgrade
        // path users actually get.
        let sockets = channels.sockets
        let socketRoutes = SocketController.alulaRoutes { _ in
            SocketController(validator: DemoTokenValidator(), sockets: sockets)
        }
        self.testClient = try TestClient(routes: socketRoutes)
        self.presence = presence
    }

    /// A client authenticated as `subject`. The token rides in the query
    /// string because a browser cannot set headers on a WebSocket handshake —
    /// the same reason the real app reads it there.
    func client(as subject: String, roles: String = "") -> ChannelClient {
        let token = roles.isEmpty ? "demo:\(subject)" : "demo:\(subject):\(roles)"
        return ChannelClient(
            url: URL(string: "alula-test:///socket")!,
            transport: InMemoryChannelTransport(testClient: testClient, query: "token=\(token)"))
    }

    /// A client with no credential at all.
    func anonymousClient() -> ChannelClient {
        ChannelClient(
            url: URL(string: "alula-test:///socket")!,
            transport: InMemoryChannelTransport(testClient: testClient))
    }
}

@Suite("Demo real-time — channels, presence, and the join gate")
struct RealtimeTests {

    @Test("an authenticated join is admitted and answers with the room")
    func joinAdmitsAuthenticated() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let client = harness.client(as: "ada")
        try await client.connect()

        let reply = try await client.channel("room:general").join()

        #expect(reply["room"]?.stringValue == "general")
        #expect(reply["name"]?.stringValue == "General")
        await client.disconnect()
    }

    @Test("an anonymous socket cannot join a room")
    func joinRejectsAnonymous() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let client = harness.anonymousClient()
        try await client.connect()

        // The gate is the join, not the connect: an anonymous socket is a
        // legitimate thing to hold — it simply cannot enter a room.
        await #expect(throws: (any Error).self) {
            try await client.channel("room:general").join()
        }
        await client.disconnect()
    }

    @Test("a room that does not exist is refused, not conjured")
    func joinRejectsUnknownRoom() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let client = harness.client(as: "ada")
        try await client.connect()

        await #expect(throws: (any Error).self) {
            try await client.channel("room:nonexistent").join()
        }
        await client.disconnect()
    }

    @Test("an archived room is refused")
    func joinRejectsArchivedRoom() async throws {
        let harness = try Harness(
            store: FakeRoomStore(rooms: [.fixture(slug: "attic", archived: true)]))
        let client = harness.client(as: "ada")
        try await client.connect()

        await #expect(throws: (any Error).self) {
            try await client.channel("room:attic").join()
        }
        await client.disconnect()
    }

    @Test("a message is persisted before it is broadcast")
    func messagePersistedThenBroadcast() async throws {
        let store = FakeRoomStore(rooms: [.fixture(slug: "general")])
        let harness = try Harness(store: store)
        let ada = harness.client(as: "ada")
        try await ada.connect()
        let channel = ada.channel("room:general")
        _ = try await channel.join()

        let reply = try await channel.push("new_msg", payload: ["body": "hello"])

        // The sender gets the canonical row back, so an optimistic render can
        // be reconciled against what was actually stored.
        #expect(reply["body"]?.stringValue == "hello")
        #expect(reply["sender"]?.stringValue == "ada")
        #expect(reply["id"]?.stringValue != nil)
        #expect(store.posted.count == 1)
        #expect(store.posted.first?.body == "hello")
        await ada.disconnect()
    }

    @Test("a failed write broadcasts nothing")
    func failedWriteDoesNotBroadcast() async throws {
        let store = FakeRoomStore(rooms: [.fixture(slug: "general")])
        store.failPosts()
        let harness = try Harness(store: store)

        let ada = harness.client(as: "ada")
        try await ada.connect()
        let adaChannel = ada.channel("room:general")
        _ = try await adaChannel.join()

        let bob = harness.client(as: "bob")
        try await bob.connect()
        let bobChannel = bob.channel("room:general")
        _ = try await bobChannel.join()

        let seen = MessageCollector(channel: bobChannel, event: "new_msg")

        await #expect(throws: (any Error).self) {
            try await adaChannel.push("new_msg", payload: ["body": "doomed"])
        }

        // Nothing stored, so nothing may have been seen. A message that fans
        // out and then fails to insert has been read by everyone and exists
        // for no one — which no retry can repair.
        #expect(store.posted.isEmpty)
        try await Task.sleep(for: .milliseconds(120))
        #expect(await seen.count == 0)

        await ada.disconnect()
        await bob.disconnect()
    }

    @Test("a message reaches the other people in the room, not its sender")
    func broadcastReachesOthers() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))

        let ada = harness.client(as: "ada")
        try await ada.connect()
        let adaChannel = ada.channel("room:general")
        _ = try await adaChannel.join()

        let bob = harness.client(as: "bob")
        try await bob.connect()
        let bobChannel = bob.channel("room:general")
        _ = try await bobChannel.join()

        let bobSaw = MessageCollector(channel: bobChannel, event: "new_msg")
        let adaSaw = MessageCollector(channel: adaChannel, event: "new_msg")

        _ = try await adaChannel.push("new_msg", payload: ["body": "hello room"])
        try await Task.sleep(for: .milliseconds(150))

        #expect(await bobSaw.bodies == ["hello room"])
        // The sender already has it, as the push reply — delivering it twice
        // is what `excluding:` exists to prevent.
        #expect(await adaSaw.count == 0)

        await ada.disconnect()
        await bob.disconnect()
    }

    @Test("presence lists everyone in the room, and drops them when they go")
    func presenceTracksMembership() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let presence = harness.presence

        let ada = harness.client(as: "ada")
        try await ada.connect()
        _ = try await ada.channel("room:general").join()

        let bob = harness.client(as: "bob")
        try await bob.connect()
        _ = try await bob.channel("room:general").join()

        try await eventually { await presence.list(topic: "room:general").count == 2 }
        let keys = await presence.list(topic: "room:general").map(\.key).sorted()
        #expect(keys == ["ada", "bob"])

        // Nothing calls untrack. Presence is bound to the socket's membership,
        // so dropping the connection is what removes them.
        await bob.disconnect()
        try await eventually { await presence.list(topic: "room:general").count == 1 }
        let remaining = await presence.list(topic: "room:general").map(\.key)
        #expect(remaining == ["ada"])

        await ada.disconnect()
    }

    @Test("one identity in two tabs is one key with two metas")
    func oneIdentityManyConnections() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let presence = harness.presence

        let tabOne = harness.client(as: "ada")
        try await tabOne.connect()
        _ = try await tabOne.channel("room:general").join()

        let tabTwo = harness.client(as: "ada")
        try await tabTwo.connect()
        _ = try await tabTwo.channel("room:general").join()

        try await eventually {
            await presence.list(topic: "room:general").first?.metas.count == 2
        }
        let entries = await presence.list(topic: "room:general")
        #expect(entries.count == 1, "one identity is one key")
        #expect(entries.first?.metas.count == 2, "two connections are two metas")

        // Closing one tab leaves the person present through the other — the
        // distinction a bare list of names would lose.
        await tabOne.disconnect()
        try await eventually {
            await presence.list(topic: "room:general").first?.metas.count == 1
        }
        #expect(await presence.list(topic: "room:general").count == 1)

        await tabTwo.disconnect()
    }

    @Test("an unknown status is refused rather than recorded")
    func statusValidation() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let ada = harness.client(as: "ada")
        try await ada.connect()
        let channel = ada.channel("room:general")
        _ = try await channel.join()

        let ok = try await channel.push("status", payload: ["status": "away"])
        #expect(ok["status"]?.stringValue == "away")

        await #expect(throws: (any Error).self) {
            try await channel.push("status", payload: ["status": "invisible"])
        }
        await ada.disconnect()
    }
}

// MARK: - Test support

/// The real-time path's only use of the digest service is "tell it something
/// changed"; nothing here asserts on caching, so the seam is satisfied and
/// ignored.
private struct NoopDigests: DigestInvalidating {
    func messagesChanged() async throws {}
}

/// Collects inbound events of one name from a channel.
private actor MessageCollector {
    private var received: [JSONValue] = []

    init(channel: ChannelHandle, event: String) {
        Task { [weak self] in
            for await message in await channel.messages() where message.event == event {
                await self?.append(message.payload)
            }
        }
    }

    private func append(_ payload: JSONValue) { received.append(payload) }

    var count: Int { received.count }
    var bodies: [String] { received.compactMap { $0["body"]?.stringValue } }
}

/// Polls until `condition` holds or the deadline passes — the shape every
/// assertion about a distributed side effect needs, since "has the diff
/// arrived yet" is not answerable synchronously.
private func eventually(
    timeout: Duration = .seconds(2),
    _ condition: () async -> Bool
) async throws {
    let deadline = ContinuousClock.now.advanced(by: timeout)
    while ContinuousClock.now < deadline {
        if await condition() { return }
        try await Task.sleep(for: .milliseconds(20))
    }
    Issue.record("condition never became true within \(timeout)")
}

"""#,
            "Tests/AppTests/RoomChannelTests.swift": #"""
import AlulaChannelsProtocol
import Foundation
import Testing

@testable import App

/// The decisions `RoomChannel` makes before it ever touches a database.
///
/// Topic parsing and the wire shape are worth pinning on their own: the topic
/// is what authorization keys off, and the wire shape is a contract two
/// separate code paths (the WebSocket handler and the REST controller) both
/// produce. If those two ever disagree, clients see the same message in two
/// shapes depending on how it was sent.
@Suite("RoomChannel — topic parsing and wire shape")
struct RoomChannelTests {

    @Test("a well-formed topic yields its room slug")
    func topicParsing() {
        #expect(RoomChannel.roomSlug(from: "room:general") == "general")
        #expect(RoomChannel.roomSlug(from: "room:a:b") == "a:b")
    }

    @Test("anything that is not this channel's shape is refused, not coerced")
    func malformedTopics() {
        // "room:" is the interesting one: dropping the prefix leaves an empty
        // string, and treating that as a room named "" would create presence
        // lists for a room nobody can name.
        for bad in ["room:", "room", "lobby", "", "rooms:general", "Room:general"] {
            #expect(RoomChannel.roomSlug(from: bad) == nil, "\(bad) should not parse")
        }
    }

    @Test("the wire shape carries exactly the public fields")
    func wireShape() throws {
        let id = UUID()
        let message = ChatMessage(
            id: id, room: "general", roomID: UUID(), sender: "ada",
            body: "hello", authorID: nil, parentID: nil,
            mentions: ["grace"], sentAt: Date(timeIntervalSince1970: 0))

        let wire = RoomChannel.wire(message)

        #expect(wire["id"]?.stringValue == id.uuidString)
        #expect(wire["room"]?.stringValue == "general")
        #expect(wire["sender"]?.stringValue == "ada")
        #expect(wire["body"]?.stringValue == "hello")
        if case .array(let mentions)? = wire["mentions"] {
            #expect(mentions.compactMap(\.stringValue) == ["grace"])
        } else {
            Issue.record("mentions should be an array")
        }
        // Internal identifiers stay internal: a client has no use for the
        // room's UUID when it already addressed the room by slug, and
        // `redacted`/`authorID` are not this event's business.
        #expect(wire["roomID"] == nil)
        #expect(wire["authorID"] == nil)
    }

    @Test("mentions are read defensively from client payload")
    func mentionsParsing() {
        #expect(RoomChannel.mentions(in: ["mentions": .array([.string("ada")])]) == ["ada"])
        // Absent, wrong-typed, and mixed payloads all degrade to something
        // sane rather than throwing — this is client input.
        #expect(RoomChannel.mentions(in: ["body": "hi"]).isEmpty)
        #expect(RoomChannel.mentions(in: ["mentions": "ada"]).isEmpty)
        #expect(RoomChannel.mentions(in: ["mentions": .array([.string("a"), .number(1)])]) == ["a"])
    }

    @Test("only known statuses are accepted")
    func statuses() {
        #expect(RoomChannel.allowedStatuses.contains("online"))
        #expect(RoomChannel.allowedStatuses.contains("away"))
        #expect(RoomChannel.allowedStatuses.contains("typing"))
        #expect(!RoomChannel.allowedStatuses.contains("invisible"))
    }
}

"""#,
            "Tests/AppTests/SessionControllerTests.swift": #"""
import AlulaCore
import AlulaRateLimit
import AlulaSecurityCore
import AlulaSessionsTesting
import AlulaWeb
import AlulaWebTesting
import Foundation
import HTTPTypes
import Testing

@testable import App

/// The whole browser sign-in path, in process: the password provider over the
/// demo's accounts, the session middleware, the security lanes, and the
/// `"csrf"` lane sign-in and sign-out name — composed the way `AppModule`
/// composes them.
@Suite("SessionController — cookie sign-in")
struct SessionControllerTests {
    private let store = RecordingSessionStore()

    private func client() throws -> TestClient {
        let sessions = try AlulaSessionsModule(
            configuration: Configuration(values: ["sessions.cookie-secure": "false"]),
            store: store)
        // No bearer validator is needed for a browser; the demo's is for its
        // APIs, and it is exercised elsewhere.
        let security = AlulaSecurityModule(validator: nil, sessions: sessions.runtime)
        // The demo's accounts, and the password provider over them — hashed
        // with cheap parameters so the suite stays fast.
        let fast = Argon2idHashing(parameters: .init(timeCost: 1, memoryCost: 8, parallelism: 1))
        let accounts = InMemoryCredentialStore()
        accounts.insert(
            StoredCredential(
                subject: "user-ada", passwordHash: try fast.hash("correct horse"),
                roles: ["admin", "author"], email: "ada@example.com", emailVerified: true,
                name: "Ada Lovelace"),
            identifiers: ["ada@example.com", "ada"])
        let provider = PasswordSignIn(
            authenticator: PasswordAuthenticator(
                store: accounts, issuer: "local", hasher: fast,
                limiter: RateLimiter(store: InMemoryRateLimitStore())))
        return try TestClient(
            routes: SessionController.alulaRoutes { _ in SessionController(provider: provider) },
            middleware:
                sessions.middleware + security.middleware
                + MiddlewareRegistration.lane("csrf", [CSRFProtection()]))
    }

    private struct Credentials: Encodable {
        let identifier: String
        let password: String
    }

    private func sessionCookie(_ response: Response) -> String? {
        response.headerValues("Set-Cookie")
            .compactMap { $0.split(separator: ";").first.map(String.init) }
            .first { $0.hasPrefix("session=") }
    }

    /// What a browser does before it can sign in: `GET /session/csrf`, which
    /// sets the cookie the token is bound to.
    private func csrf(_ client: TestClient) async throws -> (cookie: String, token: String) {
        let response = await client.get("/session/csrf")
        #expect(response.status == .ok)
        let cookie = try #require(sessionCookie(response))
        return (cookie, try response.decodeJSON(SessionController.CSRFToken.self).csrfToken)
    }

    /// Signs in the way a browser does, and returns the new cookie and the
    /// token, which signing in keeps.
    private func signIn(
        _ client: TestClient, as identifier: String = "ada@example.com",
        password: String = "correct horse"
    ) async throws -> (cookie: String, token: String) {
        let (cookie, token) = try await csrf(client)
        let response = try await client.post(
            "/session/", headers: [.cookie: cookie, .xCSRFToken: token],
            json: Credentials(identifier: identifier, password: password))
        #expect(response.status == .noContent)
        return (try #require(sessionCookie(response)), token)
    }

    @Test("beginning describes the password form — the fields a front end draws")
    func beginDescribesTheForm() async throws {
        let response = await (try client()).get("/session/sign-in")
        #expect(response.status == .ok)
        let form = try response.decodeJSON(SignInForm.self)
        #expect(form.fields.map(\.name) == ["identifier", "password"])
        #expect(form.fields.last?.autocomplete == "current-password")
    }

    @Test("an anonymous browser is refused; a signed-in one is recognised by its cookie")
    func signInRoundTrip() async throws {
        let client = try client()
        #expect(await client.get("/session/").status == .unauthorized)

        let (cookie, token) = try await signIn(client)
        let who = await client.get("/session/", headers: [.cookie: cookie])
        #expect(who.status == .ok)
        let identity = try who.decodeJSON(SessionController.WhoAmI.self)
        #expect(identity.subject == "user-ada")
        #expect(identity.email == "ada@example.com")
        #expect(identity.name == "Ada Lovelace")
        #expect(identity.roles == ["admin", "author"])
        // Minted anonymously, kept across the sign-in's id regeneration.
        #expect(identity.csrfToken == token)
    }

    @Test("a wrong password is a 401 and signs nobody in")
    func refused() async throws {
        let client = try client()
        let (cookie, token) = try await csrf(client)
        #expect(store.entryCount == 1, "minting the token is the one anonymous write")

        let response = try await client.post(
            "/session/", headers: [.cookie: cookie, .xCSRFToken: token],
            json: Credentials(identifier: "ada@example.com", password: "wrong"))
        #expect(response.status == .unauthorized)
        #expect(response.header("Set-Cookie") == nil)
        #expect(await client.get("/session/", headers: [.cookie: cookie]).status == .unauthorized)
    }

    @Test("login CSRF: a sign-in without the token is refused, form-encoded or not")
    func signInWithoutTokenRefused() async throws {
        let client = try client()

        // What a hostile page's auto-submitting form sends: form-encoded, no
        // cookie of this site's at all, no token. The password provider
        // accepts form encoding, and a form needs no preflight — so without
        // the guard this would sign the visitor in as the attacker.
        let forged = await client.post(
            "/session/", headers: [.contentType: "application/x-www-form-urlencoded"],
            body: Data("identifier=mallory%40example.com&password=hunter2".utf8))
        #expect(forged.status == .forbidden)
        #expect(sessionCookie(forged) == nil)

        // The same with a real session cookie but no token.
        let (cookie, _) = try await csrf(client)
        let noToken = try await client.post(
            "/session/", headers: [.cookie: cookie],
            json: Credentials(identifier: "ada@example.com", password: "correct horse"))
        #expect(noToken.status == .forbidden)
        #expect(await client.get("/session/", headers: [.cookie: cookie]).status == .unauthorized)
    }

    @Test("signing out regenerates the id and the old cookie no longer signs anyone in")
    func signOut() async throws {
        let client = try client()
        let (cookie, token) = try await signIn(client)

        let out = await client.delete(
            "/session/", headers: [.cookie: cookie, .xCSRFToken: token])
        #expect(out.status == .noContent)
        #expect(sessionCookie(out) != cookie)
        #expect(await client.get("/session/", headers: [.cookie: cookie]).status == .unauthorized)
    }

    @Test("signing out with no CSRF token, or the wrong one, is refused — the cookie still signs in")
    func signOutWithoutTokenRefused() async throws {
        let client = try client()
        let (cookie, _) = try await signIn(client)

        #expect(await client.delete("/session/", headers: [.cookie: cookie]).status == .forbidden)
        #expect(
            await client.delete(
                "/session/", headers: [.cookie: cookie, .xCSRFToken: "not-the-real-token"]
            ).status == .forbidden)
        #expect(await client.get("/session/", headers: [.cookie: cookie]).status == .ok)
    }
}

extension HTTPField.Name {
    /// The demo's tests live outside `AlulaWeb`, so this is the public name
    /// — the same literal `CSRFProtection` checks internally, declared here
    /// because a test has no reason to `@testable import` the framework.
    fileprivate static let xCSRFToken = HTTPField.Name("x-csrf-token")!
}

"""#,
            "Tests/AppTests/Support/FakeRoomStore.swift": #"""
import Foundation
import Synchronization

@testable import App

/// An in-memory `RoomStore`, so the real-time suite exercises the real
/// Channels/PubSub/Presence stack with no database anywhere in it.
///
/// It records what was written, which is how the tests assert the property
/// that matters most in `RoomChannel`: the message is persisted *before* it is
/// broadcast, never the other way round.
final class FakeRoomStore: RoomStore, Sendable {
    struct State {
        var rooms: [String: Room] = [:]
        var authors: [String: UUID] = [:]
        var posted: [ChatMessage] = []
        /// Set to make `post` fail, so the broadcast-on-failure path can be
        /// tested rather than assumed.
        var postFails = false
    }

    private let state = Mutex(State())

    init(rooms: [Room] = [], authors: [String: UUID] = [:]) {
        state.withLock {
            $0.rooms = Dictionary(uniqueKeysWithValues: rooms.map { ($0.slug, $0) })
            $0.authors = authors
        }
    }

    var posted: [ChatMessage] { state.withLock { $0.posted } }

    func failPosts() { state.withLock { $0.postFails = true } }

    // MARK: RoomStore

    func room(slug: String, messageLimit: Int) async throws -> Room? {
        state.withLock { $0.rooms[slug] }
    }

    func authorIDs(forNames names: [String]) async throws -> [String: UUID] {
        state.withLock { store in
            store.authors.filter { names.contains($0.key) }
        }
    }

    func post(_ messages: [ChatMessage]) async throws -> [ChatMessage] {
        try state.withLock { store in
            if store.postFails { throw FakeError.postRefused }
            store.posted.append(contentsOf: messages)
            return messages
        }
    }

    enum FakeError: Error { case postRefused }
}

extension Room {
    /// A room with the fields the real-time path reads; the rest is filler.
    static func fixture(slug: String, name: String? = nil, archived: Bool = false) -> Room {
        Room(
            id: UUID(), slug: slug, name: name ?? slug.capitalized,
            archived: archived, createdAt: Date())
    }
}

